import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer("");
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int n = Integer.parseInt(tokens.get(0)), m = Integer.parseInt(tokens.get(1));
        // every non-empty decimal prefix of every number in arr1
        HashSet<String> prefixes = new HashSet<>();
        for (int i = 0; i < n; i++) {
            String s = tokens.get(2 + i);
            for (int end = 1; end <= s.length(); end++) prefixes.add(s.substring(0, end));
        }
        int answer = 0;
        for (int i = 0; i < m; i++) {
            String s = tokens.get(2 + n + i);
            for (int end = 1; end <= s.length(); end++) {
                if (!prefixes.contains(s.substring(0, end))) break;
                answer = Math.max(answer, end);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var n, m int
	fmt.Fscan(in, &n, &m)
	// every non-empty decimal prefix of every number in arr1
	prefixes := make(map[string]bool, 10*n)
	for i := 0; i < n; i++ {
		var s string
		fmt.Fscan(in, &s)
		for end := 1; end <= len(s); end++ {
			prefixes[s[:end]] = true
		}
	}
	answer := 0
	for i := 0; i < m; i++ {
		var s string
		fmt.Fscan(in, &s)
		for end := 1; end <= len(s); end++ {
			if !prefixes[s[:end]] {
				break
			}
			answer = max(answer, end)
		}
	}
	fmt.Println(answer)
}
